import{_ as a,a as t,o as r,a2 as s}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Generative AI (Magic AI)","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/introduction.md","filePath":"generative-ai/introduction.md","lastUpdated":1789441803000}'),o={name:"generative-ai/introduction.md"};function n(i,e,c,l,h,d){return r(),t("div",null,e[0]||(e[0]=[s('<h1 id="generative-ai-magic-ai" tabindex="-1">Generative AI (Magic AI) <a class="header-anchor" href="#generative-ai-magic-ai" aria-label="Permalink to &quot;Generative AI (Magic AI)&quot;">​</a></h1><div class="feature-hero feature--ai"><span class="feature-hero__eyebrow">Built into Bagisto</span><p class="feature-hero__lead">Draft product and page content, create product images, let shoppers search with a photo, translate reviews and thank each customer with a personal message. Generative AI is part of Bagisto itself. The admin panel calls it <strong>Magic AI</strong>, and it works with the AI provider you choose.</p><div class="feature-hero__actions"><a class="feature-hero__btn feature-hero__btn--primary" href="/configure/magic-ai.html">Set up Generative AI</a><a class="feature-hero__btn feature-hero__btn--ghost" href="#what-you-can-do">Explore the features</a></div><ul class="feature-hero__chips" aria-label="Supported AI providers"><li>Anthropic</li><li>DeepSeek</li><li>Gemini</li><li>Groq</li><li>Mistral</li><li>Ollama</li><li>OpenAI</li><li>xAI</li></ul></div><h2 id="what-you-can-do" tabindex="-1">What you can do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What you can do&quot;">​</a></h2><div class="feature-cards feature--ai"><a class="feature-card" href="/generative-ai/generate-content.html"><span class="feature-card__icon feature-card__icon--text" aria-hidden="true"></span><span class="feature-card__title">Generate text content</span><span class="feature-card__desc">Draft product descriptions, category text, CMS pages and email templates from a prompt, right in the editor.</span><span class="feature-card__tag">Admin panel</span></a><a class="feature-card" href="/generative-ai/generate-images.html"><span class="feature-card__icon feature-card__icon--image" aria-hidden="true"></span><span class="feature-card__title">Generate product images</span><span class="feature-card__desc">Create images from a written description in the size and quality you choose, then keep the ones you like.</span><span class="feature-card__tag">Admin panel</span></a><a class="feature-card" href="/generative-ai/image-search.html"><span class="feature-card__icon feature-card__icon--camera" aria-hidden="true"></span><span class="feature-card__title">AI image search</span><span class="feature-card__desc">Shoppers search with a photo. The model lists what it sees, and the storefront shows matching products.</span><span class="feature-card__tag">Storefront</span></a><a class="feature-card" href="/generative-ai/review-translation.html"><span class="feature-card__icon feature-card__icon--translate" aria-hidden="true"></span><span class="feature-card__title">Review translation</span><span class="feature-card__desc">Shoppers read a product review in their own language with one click on <strong>Translate</strong>.</span><span class="feature-card__tag">Storefront</span></a><a class="feature-card" href="/generative-ai/checkout-message.html"><span class="feature-card__icon feature-card__icon--message" aria-hidden="true"></span><span class="feature-card__title">Personalized checkout message</span><span class="feature-card__desc">Thank each customer on the order confirmation page with a short message about what they bought.</span><span class="feature-card__tag">Storefront</span></a><a class="feature-card" href="/configure/magic-ai.html"><span class="feature-card__icon feature-card__icon--settings" aria-hidden="true"></span><span class="feature-card__title">Configuration</span><span class="feature-card__desc">Switch Magic AI on, connect your providers and choose the model each feature uses.</span><span class="feature-card__tag">Configure &gt;&gt; Magic AI</span></a></div><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol class="feature-steps feature--ai"><li><span class="feature-steps__title">Connect a provider</span>Save an API key for OpenAI, Anthropic, Gemini, Groq, xAI, DeepSeek or Mistral, or the address of an Ollama server.</li><li><span class="feature-steps__title">Switch on the features</span>Turn on the features you want. Choose which providers admins can pick from, and the model each storefront feature uses.</li><li><span class="feature-steps__title">Review, then apply</span>Admin features show their result in a dialog first. Nothing is added to your store until you click <strong>Apply</strong> and save.</li></ol><h2 id="where-each-feature-appears" tabindex="-1">Where each feature appears <a class="header-anchor" href="#where-each-feature-appears" aria-label="Permalink to &quot;Where each feature appears&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Where it appears</th><th>What starts it</th></tr></thead><tbody><tr><td><a href="./generate-content.html">Generate text content</a></td><td>The <strong>Magic AI</strong> button in the admin&#39;s rich-text editors</td><td>You click <strong>Generate</strong></td></tr><tr><td><a href="./generate-images.html">Generate product images</a></td><td>The <strong>Magic AI</strong> tile beside <strong>Add Image</strong> in the admin&#39;s image uploaders</td><td>You click <strong>Generate</strong></td></tr><tr><td><a href="./image-search.html">AI image search</a></td><td>The camera icon in the storefront search bar</td><td>A shopper chooses a photo</td></tr><tr><td><a href="./review-translation.html">Review translation</a></td><td>The <strong>Translate</strong> button under each review on a product page</td><td>A shopper clicks <strong>Translate</strong></td></tr><tr><td><a href="./checkout-message.html">Personalized checkout message</a></td><td>The order confirmation page</td><td>A shopper places an order</td></tr></tbody></table><h2 id="providers-and-models" tabindex="-1">Providers and models <a class="header-anchor" href="#providers-and-models" aria-label="Permalink to &quot;Providers and models&quot;">​</a></h2><ul><li><strong>Text generation, review translation and the checkout message work with all eight providers.</strong></li><li><strong>AI image search needs a model that can read images.</strong> With a text-only model, photo search falls back to the simpler recognition in the shopper&#39;s browser, without any message.</li><li><strong>Image generation works with the image models of OpenAI, Gemini and xAI.</strong></li><li><strong>In the admin panel, you pick the model each time you generate.</strong> The list holds the models of the providers you allowed for that feature.</li><li><strong>Each storefront feature uses the model you set for it on each channel.</strong></li><li><strong>Ollama runs open models on a server you choose.</strong> When that server runs on your own infrastructure, requests to it stay there.</li><li><strong>Each request is billed by the provider of the chosen model</strong>, except requests to your own Ollama server.</li></ul><h2 id="you-stay-in-control" tabindex="-1">You stay in control <a class="header-anchor" href="#you-stay-in-control" aria-label="Permalink to &quot;You stay in control&quot;">​</a></h2><p>Magic AI doesn&#39;t run your store by itself. It doesn&#39;t publish content, change prices, place orders or answer customers&#39; questions.</p><ul><li><strong>In the admin panel</strong>, generated text and images go into a product, page or template only after you click <strong>Apply</strong> and save.</li><li><strong>On the storefront</strong>, a feature runs only when a shopper acts: a photo is analyzed when they search with it, a review is translated when they click <strong>Translate</strong>, and the checkout message is written when their order confirmation page opens.</li><li><strong>Storefront results go straight to the shopper, without your review.</strong> Test each feature on a few orders and reviews before you switch it on for a channel.</li></ul><p>AI models can produce wrong or misleading text and images. Check names, numbers and claims before you apply a result.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>All the settings live under <strong>Configure &gt;&gt; Magic AI</strong>. Follow <a href="./../configure/magic-ai.html">Generative AI (Magic AI)</a> under Configure to switch the features on, connect a provider and choose models. Then open the page for the feature you want to use.</p>',16)]))}const g=a(o,[["render",n]]);export{p as __pageData,g as default};
